"use strict";
var quill_change = null;
$(document).ready(function () {

    $("#project-type").validate(), $("#project-details").validate(), $("#project-settings").validate(), $("#project-budgets").validate(), $("#project-create-steps").steps({
        headerTag: "div.step-title",
        bodyTag: "section.step-body",
        transitionEffect: "slideLeft",
        titleTemplate: "#title#",
        enableAllSteps: !0,
        onStepChanging: function (e, t, n) {
            return n < t || 1 != (n = $(".body.current form")).length || (n.validate().settings.ignore = ":disabled,:hidden", n.valid())
        },
        onFinishing: function (e, t) {
            var n = $(".body.current form");
            return 1 != n.length || (n.validate().settings.ignore = ":disabled", n.valid())
        },
        onFinished: function (e, t) {
            const n = Swal.mixin({
                customClass: {
                    confirmButton: "btn btn-success m-1",
                    cancelButton: "btn btn-danger m-1"
                },
                buttonsStyling: !1
            });
            n.fire({
                title: "Все готово?",
                text: "Вы уверены, что все готово и товар можно обновлять?",
                icon: "warning",
                showCancelButton: !0,
                confirmButtonText: "Да, все готово!",
                cancelButtonText: "Нет, отмена!",
                reverseButtons: !0,
                type: "success"
            }).then(e => {
                if (e.value) {
                    var prod_id = $("input[name='product_id']").val();
                    var description = null;
                    description = $(".ql-editor").html();
                    $.post('/admin_products/admin_manage_products/edit/form/submit/' + prod_id, { type: $("input[name='type_id']").val(), info: $("#project-details").serializeArray(), description: description, prices: $("#project-price").serializeArray(), images: $("#project-images").serializeArray() }, function (data) {
                        console.log(data);
                        if (data > 0) {
                            $.post('/admin_products/admin_manage_products/edit/form/submit/' + prod_id + '/update_params/' + data, $("#project-params").serialize(), function (result) {
                                //    console.log(result);
                                n.fire("Товар отредактирован!", "Товар успешно изменен.", "success").then(e => {
                                    window.location.href = '/admin_products/admin_manage_products/';
                                });
                            });
                        } else {
                            e.dismiss === Swal.DismissReason.cancel;
                            n.fire("Ошибка", "Во время сохранения товара, что то пошло не так", "error");
                        }
                    });
                } else {
                    e.dismiss === Swal.DismissReason.cancel;
                    n.fire("Отменено", "Вы отменили изменение товара :)", "error");
                }
            })
        }
    }),
        $("#productGroup, #tragetAssigned").select2({
            theme: "bootstrap-5",
        }),
        $("#billingType, #projectStatus, #projectTags, #tragetTags, [data-select2-teammates='teammates']").select2({
            theme: "bootstrap-5",
            templateResult: bgformat,
            templateSelection: bgformat
        }), $("#sendcontactsNotifications").select2({
            theme: "bootstrap-5",
            templateResult: iformat,
            templateSelection: iformat
        })

    $("#ProductArticle").on('input', function () {
        this.value = this.value.replace(/[^0-9a-z\s]/gi, '');
        $("#validationArticleFeedback").remove();
    });

    $("#ProductArticle").on('change', function () {
        var error = "<div id=\"validationArticleFeedback\" class=\"invalid-feedback\">Товар с таким артикулом уже существует!</div>";
        $.post('/admin_products/admin_manage_products/form/create/article_check', { article: $(this).val() }, function (data) {
            if (data) {
                $("#ProductArticle").val('');
                $(".article").append(error);
                $("#ProductArticle").addClass('is-invalid');
            }
        });
    });
    $('#ProductWeight').on('input', function () {
        this.value = this.value.replace(/[^0-9.]/, '');
    });
    $( "#js-file-list" ).sortable();
}),
    $(document).ready(function () {
        var e = document.getElementById("projectReleaseDate"),
            t = document.getElementById("targetReleaseDate");
        new Datepicker(e, {
            clearBtn: !0,
            allowOneSidedRange: !0
        }), new Datepicker(t, {
            clearBtn: !0,
            allowOneSidedRange: !0
        })
    }),
    $(document).ready(function () {
        $("#choose-file").change(function () {
            $(this).prev("label").clone();
            var e = $("#choose-file")[0].files[0].name;
            $(this).prev("label").text(e)
        })
    });
$(document).ready(function () {
    $("#choose-file").change(function(){
        // alert("Все сработало");
        if (window.FormData === undefined) {
            alert('В вашем браузере загрузка файлов не поддерживается');
        } else {
            var formData = new FormData();
            $.each($("#choose-file")[0].files, function(key, input){
                formData.append('file[]', input);
            });

            $.ajax({
                type: 'POST',
                url: '/products/manage_products/create/temp_uploads',
                cache: false,
                contentType: false,
                processData: false,
                data: formData,
                dataType : 'json',
                success: function(msg){
                    msg.forEach(function(row) {
                        if (row.error == '') {
                            $('#js-file-list').append(row.data);
                        } else {
                            alert(row.error);
                        }
                    });
                    $("#choose-file").val('');
                    $("#choose-file-label").html('Выберете файл');
                }
            });
        }
    });
}),
    $(document).ready(function () {
        let value = $("input[name=\"type_id\"]").val();
        let product_id = $("input[name=\"product_id\"]").val();

        $.post('/admin_products/admin_manage_products/edit/select_subtype', { type: value, product_id: product_id }, function (data) {
            var result = jQuery.parseJSON(data);
            $('#project-create-steps').steps('insert', 2, {
                title: 'Цены',
                content: result.price,
            });
            if (result.params.status) {
                $('#project-create-steps').steps('insert', 3, {
                    title: 'Параметры',
                    content: result.params.form,
                });
                $.each($('#productParamSelect').val(), function (index, value) {
                    $.post('/admin_products/admin_manage_products/edit/select_params', { id: value, product_id: product_id }, function (result) {
                        $("#params_form").append(result);
                    });
                });
                $("#productParamSelect").select2({
                    theme: "bootstrap-5",
                    templateResult: bgformat,
                    templateSelection: bgformat
                })
                $('#productParamSelect').on('select2:select', function (e) {
                    var data = e.params.data;
                    $.post('/admin_products/admin_manage_products/create/select_params', { id: data.id, name: data.text }, function (result) {
                        $("#params_form").append(result);
                    });
                });
                $('#productParamSelect').on('select2:unselect', function (e) {
                    var data = e.params.data;
                    $(".param" + data.id).remove();
                });
            }
            if (result.type.form) {
                var tab = 3;
                var form_arr = jQuery.parseJSON(result.type.form);
                $.each(form_arr, function (index, value) {
                    tab++;
                    // console.log(tab);
                    $('#project-create-steps').steps('insert', tab, {
                        title: value.name,
                        content: value.form
                    });
                });
                $('#c').change(function () {
                    // ajax_form();
                });
            }
        });
    });
var quill_description = null;
$(document).ready(function () {
    const quill_options = {
        // debug: 'info',
        modules: {
            toolbar: true,
        },
        placeholder: 'Compose an epic...',
        theme: 'snow'
    };
    quill_description = new Quill('#projectDescription', quill_options);
});
quill_description.on('text-change', (delta, oldDelta, source) => {
    quill_change = true;
});
function get_quill_text(quill = quill_description) {
    return quill.getSemanticHTML(0);
}
function delete_photo(id) {
    var photo_block = $('#' + id).parent().parent().parent().parent().parent().parent();
    $.post('/admin_products/admin_manage_products/form/edit/delete_photo/', { image: photo_block.parent().find("img").attr("src") }, function (data) {
        if (data > 0) {
            photo_block.remove();
        }
    });
}
